import { useState, type FormEvent } from 'react';
import {
  JxAlert,
  JxButton,
  JxInputField,
  JxSelect,
  JxSwitch,
} from '@jinx-ui/react';

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'Только чтение' },
  { value: 'editor', label: 'Редактор', meta: 'Правка материалов' },
  { value: 'admin', label: 'Администратор', meta: 'Полный доступ' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [role, setRole] = useState('viewer');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const trimmedEmail = email.trim();
  const isEmailValid = EMAIL_PATTERN.test(trimmedEmail);
  const errorText =
    trimmedEmail.length > 0 && !isEmailValid
      ? 'Похоже, это не адрес почты. Пример: name@company.com'
      : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isEmailValid) return;
    setInvitedEmail(trimmedEmail);
    setEmail('');
  };

  return (
    <div style={{ display: 'grid', gap: '16px', maxWidth: '420px' }}>
      {invitedEmail && (
        <JxAlert
          intent="success"
          title="Приглашение отправлено"
          role="status"
          style={{ display: 'grid', gap: '12px' }}
        >
          <span>Мы пригласили {invitedEmail} в команду.</span>
          <span>
            <JxButton
              variant="ghost"
              size="sm"
              onClick={() => setInvitedEmail(null)}
            >
              Закрыть
            </JxButton>
          </span>
        </JxAlert>
      )}

      <form onSubmit={submit} style={{ display: 'grid', gap: '16px' }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          name="email"
          required
          autoComplete="email"
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          helperText="Приглашение придёт на этот адрес и будет действовать 7 дней."
          errorText={errorText}
        />

        <JxSelect
          label="Роль в команде"
          options={ROLES}
          value={role}
          onValueChange={setRole}
          placeholder="Выберите роль"
        />

        <JxSwitch
          label="Отправить уведомление по почте"
          name="notify"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <div style={{ display: 'flex', gap: '8px' }}>
          <JxButton type="submit" variant="primary" disabled={!isEmailValid}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </div>
  );
}

